/** Returns markup for the Akazie mark. $class is applied to the wrapping <svg>. */
function akazie_mark_svg( $class = '' ) {
	return '<svg class="' . esc_attr( $class ) . '" viewBox="0 0 1500 1500" role="img" aria-label="' . esc_attr( get_bloginfo( 'name' ) ) . '"><use href="#akazie-mark"></use></svg>';
}

/** Returns markup for one of the line icons registered above (e.g. 'ic-home'). */
function akazie_icon( $id, $class = 'ic' ) {
	return '<svg class="' . esc_attr( $class ) . '" viewBox="0 0 24 24" aria-hidden="true"><use href="#' . esc_attr( $id ) . '"></use></svg>';
}
